INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (1, 'seed', 'placeholder', '皮脂による毛髪の可塑化を抑制する高分子被膜', '疎水性セグメントと親水性セグメントを特定比率で含有するブロック共重合体を毛髪表面に薄膜として形成させることにより、皮脂の浸透を抑制しつつ柔軟性を保持する被膜を得る。被膜は毛髪1本ごとを均一に被覆し、繊維間の凝集を物理的に阻害する。', '従来の整髪料は皮膜形成性樹脂により造形を固定していたが、皮脂への耐性が十分でなく、経時的に可塑化が進行するという限界があった。耐水性を高める手法は知られていたが、耐皮脂性に着目した被膜設計の報告は限られていた。', '整髪剤を塗布した毛髪は、時間の経過とともに分泌される皮脂の可塑化作用を受け、繊維間の凝集が進行して形状保持性が著しく低下する。特に高温多湿の環境下では顕著であり、塗布直後の造形を長時間維持することが困難であった。', 'https://example.invalid/placeholder/0001', '2023-04-12', 'ヘアスタイリング', 'R&D', '皮脂で髪がベタついて固まるのを防ぐ技術', NULL, NULL, '1772745e7717a1747518b259605ad90f1a600cf45fe15d39831b9a94b60dbdb5', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (2, 'seed', 'placeholder', '耐皮脂性スタイリング用樹脂組成物', 'シリコーン変性アクリル樹脂と多価アルコールを併用した組成物により、皮脂共存下でも弾性率の低下を抑制する。光沢度の上昇を抑えるためシリカ微粒子を分散させ、質感を制御する。', '整髪料用樹脂としてはアクリル系およびウレタン系が広く用いられてきたが、いずれも油分共存下での物性変化が避けられなかった。', '皮脂分泌量の多い頭皮環境では、樹脂皮膜が可塑化して造形保持力が低下するとともに、光沢が過度に増大して外観品位を損なう。造形力と質感の両立が課題であった。', 'https://example.invalid/placeholder/0002', '2022-11-08', 'ヘアスタイリング', 'R&D', '汗や皮脂が出ても髪型が保てるようにする素材の技術', NULL, NULL, '90af7e71915fd9aa815cf9eab5d0eb61c127317d437d15aa3ad2e0ba7fd9a497', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (3, 'seed', 'placeholder', '毛髪キューティクルの水分保持機構と補修基剤', '加水分解ケラチンと分岐脂肪酸エステルを組み合わせ、損傷部位に選択的に吸着させることで水分蒸散を抑制する。繊維表面のエネルギー状態を均一化し、繊維間の反発を低減する。', '毛髪補修剤としてはタンパク質誘導体の利用が一般的であったが、吸着選択性が低く、健常部位にも付着して感触を損ねる問題があった。', '化学処理や熱処理を受けた毛髪では、キューティクルの損傷により内部水分の蒸散が促進され、繊維の膨潤と広がりを生じる。外観のまとまりが損なわれる点が課題である。', 'https://example.invalid/placeholder/0003', '2024-02-20', 'ヘアケア', 'R&D', '傷んだ髪の水分が逃げるのを抑えて、広がりにくくする技術', NULL, NULL, '5e7a4dcbbd0628c184d432b9912dbd89c1969961f1a9e8dc40818d8ee63c7f4c', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (4, 'seed', 'placeholder', '毛髪繊維間の摩擦係数低減によるコンディショニング', 'カチオン性界面活性剤と高級アルコールからなるラメラ構造体を形成し、繊維表面に潤滑層を付与する。動摩擦係数を低減させ、櫛通り時の機械的負荷を軽減する。', '潤滑成分としてシリコーン油が広く用いられてきたが、蓄積による重さの発生が指摘されていた。', '湿潤状態の毛髪は繊維表面の摩擦係数が上昇し、櫛通り時の抵抗が増大する。この抵抗はキューティクルの剥離を誘発し、損傷を進行させる要因となる。', 'https://example.invalid/placeholder/0004', '2021-09-30', 'ヘアケア', 'R&D', '髪をとかすときの引っかかりを減らして、傷みにくくする技術', NULL, NULL, 'a0f7214a6053626798e3739f5370edc685fdd1b415d170dcae1f2d897b1a8718', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (5, 'seed', 'placeholder', '角層バリア機能を補助する保湿基剤', '擬似セラミドと多価アルコールを組み合わせたラメラ構造形成基剤により、細胞間脂質の配列を補完する。経表皮水分蒸散量の増大を抑制し、角層の柔軟性を維持する。', '保湿剤としてはグリセリン等の吸湿性成分が主流であったが、バリア構造そのものを補完する設計は限られていた。', '洗浄後の角層は細胞間脂質が流出し、経表皮水分蒸散量が増大する。この状態では外部刺激に対する感受性が高まり、不快感を生じやすい。', 'https://example.invalid/placeholder/0005', '2023-07-15', 'スキンケア', 'R&D', '洗ったあとの肌から水分が逃げるのを防ぐ技術', NULL, NULL, 'b9e408cd55e58b36fe03f44711ef15943da43adbe313f2f0115788f7f8ce1722', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (6, 'seed', 'placeholder', '低刺激性界面活性剤による洗浄系の設計', 'アミノ酸系界面活性剤と両性界面活性剤を特定比率で配合し、ミセル径を制御することで、タンパク質変性を抑制しつつ十分な洗浄性能を確保する。', '低刺激性洗浄剤の開発は進んできたが、泡質と洗浄力を維持したまま刺激を低減する処方設計は難易度が高いとされてきた。', '洗浄力の高い界面活性剤は角層タンパク質の変性を引き起こし、刺激感の原因となる。洗浄性能と低刺激性の両立が長年の課題であった。', 'https://example.invalid/placeholder/0006', '2022-05-25', 'スキンケア', 'R&D', '肌への負担を抑えながらしっかり洗える洗浄成分の技術', NULL, NULL, 'f4c62eb23385fb6b022efe73db8e0c261323a372e6c5e3e7bc602480d1f09b93', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (7, 'seed', 'placeholder', '発汗環境下における化粧膜の密着性向上', '疎水化処理した板状粉体と揮発性シリコーンを組み合わせ、皮膚表面に連続的な膜を形成する。水分および油分の共存下でも界面の密着性を維持する。', '耐水性を付与する処方は確立されていたが、水分と油分が同時に存在する条件での密着維持は十分に解決されていなかった。', '発汗および皮脂分泌により化粧膜と皮膚界面の密着性が低下し、膜の部分的な剥離や移行が生じる。外観の均一性が損なわれる点が課題である。', 'https://example.invalid/placeholder/0007', '2024-06-03', 'メイクアップ', 'R&D', '汗や皮脂が出てもメイクが落ちにくくする技術', NULL, NULL, 'b21507176c964b2340945117f5cbc76b57fd4a67aee12592c342c00d2bd06856', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (8, 'seed', 'placeholder', '紫外線吸収剤の光安定化と配合技術', 'トリアジン系吸収剤と光安定化剤を併用し、励起エネルギーを効率的に失活させる系を構築する。分解速度を抑制し、防御性能の持続時間を延長する。', '紫外線防御製品の性能指標は塗布直後の値で評価されることが多く、経時的な性能低下に着目した設計は限定的であった。', '有機系紫外線吸収剤は光照射により分解し、経時的に防御性能が低下する。塗布後の時間経過とともに実効的な防御能が失われる点が課題である。', 'https://example.invalid/placeholder/0008', '2023-01-18', 'サンケア', 'R&D', '日焼け止めの効果が時間とともに弱まるのを防ぐ技術', NULL, NULL, 'c14bc127a3b80d0e1509c18a46e4c0d37411493c1efba037465947e967ee1a0c', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (9, 'seed', 'placeholder', '香料成分の徐放性マイクロカプセル', '多層構造のマイクロカプセルに香料を内包し、摩擦刺激により段階的に放出させる。揮散速度を制御することで香調の経時変化を抑制する。', '包接化合物による徐放技術は知られていたが、放出のトリガーを制御する手法には改善の余地があった。', '揮発性の高い香料成分は塗布直後に大部分が揮散し、持続性が得られない。香調の経時変化も大きく、設計意図どおりの印象を維持できない。', 'https://example.invalid/placeholder/0009', '2021-12-07', 'フレグランス', 'R&D', '香りが長もちするように、少しずつ出す仕組みの技術', NULL, NULL, '718fd4a228fea3eeae8aa4cf580f99bfcb163c4c2cd4766c0742ef2a5c2c3f58', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (10, 'seed', 'placeholder', '油中水型乳化組成物の経時安定性改善', '界面活性剤の親水親油バランスを最適化し、油相に増粘剤を配合して内水相の移動を抑制する。加速試験条件下での分離発生を有意に遅延させる。', '乳化安定性の向上は製剤設計の基本課題であり、多数の手法が検討されてきたが、使用感を損なわずに安定性を高める設計が求められていた。', '油中水型乳化物は内水相の合一により経時的に分離を生じやすく、保存期間中の品質維持が困難である。高温条件下では特に顕著となる。', 'https://example.invalid/placeholder/0010', '2022-08-11', '製剤基盤', 'R&D', '化粧品が時間とともに分離してしまうのを防ぐ技術', NULL, NULL, '6ef365dad2be6764060808f32e1c4a26103731801a02968daa9c1b6796b4d4d0', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (11, 'need', 'dummy', '夕方になると前髪がベタついて束になる', '朝しっかりワックスでセットしても、夕方には前髪がベタッとしてきて、束になって垂れてきます。一日中セットしたてのままでいたいです。', NULL, NULL, NULL, NULL, 'ヘアスタイリング', 'MK', NULL, NULL, NULL, '6463884c595180754f1c7bece0addb3a03c631a5793f1f2e4b233113ac41e606', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (12, 'need', 'dummy', '昼には髪型が崩れてしまう', '朝がんばって整えた髪型が、お昼ごろにはもうぺたんこになっています。直しても夕方まで持ちません。', NULL, NULL, NULL, NULL, 'ヘアスタイリング', 'MK', NULL, NULL, NULL, '1a3083ba06a5eeece60ab00e2eaffdb2a497fae4f7b9f5fb88684b8b961a85f2', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (13, 'need', 'dummy', '髪がパサついて広がる', 'カラーをしてから髪がパサパサして、湿気の多い日はふくらんでまとまりません。朝とかしてもすぐ広がります。', NULL, NULL, NULL, NULL, 'ヘアケア', 'MK', NULL, NULL, NULL, 'dd7f8af089504b451ea5d9094093f621eb62f93b9e1ca6d21d25159f72c40d05', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (14, 'need', 'dummy', '髪をとかすときにきしんで引っかかる', 'お風呂あがりに髪をとかすと、きしんで引っかかって、ぶちぶち切れてしまうのが気になります。', NULL, NULL, NULL, NULL, 'ヘアケア', 'MK', NULL, NULL, NULL, 'a97353eca7f20d9275c657fb06ad72cb8218fe3f094dcf3211f7f376050e7e5e', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (15, 'need', 'dummy', '洗顔後すぐに肌がつっぱる', '顔を洗ったあと、化粧水をつけるまでの間に肌がつっぱってこわばります。冬場は特につらいです。', NULL, NULL, NULL, NULL, 'スキンケア', 'MK', NULL, NULL, NULL, 'a9e24f7a7d6fa6557d7270f8a8664b3187cec5f667117088ee9f992c20b1d8ae', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (16, 'need', 'dummy', '洗うと肌がヒリヒリしてかゆくなる', 'さっぱり洗えるものを使うと、あとで肌がヒリヒリしたりかゆくなったりします。でも洗い足りないのも嫌です。', NULL, NULL, NULL, NULL, 'スキンケア', 'MK', NULL, NULL, NULL, 'dc18a800ff1f1b17e7a4d695a9613a99e4c991b245d41cad07477b1552373bb1', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (17, 'need', 'dummy', '汗をかくとメイクが落ちる', '夏場、少し歩いただけで汗でメイクがよれて落ちてしまいます。仕事中は直す時間がありません。', NULL, NULL, NULL, NULL, 'メイクアップ', 'MK', NULL, NULL, NULL, 'db3e82af258ceaea9ec43a3daecdca73627be821c58c5f34feda89a2791781c8', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (18, 'need', 'dummy', '日焼け止めを塗っても夕方には焼けている', '朝に日焼け止めを塗っていても、外にいる日は夕方になると焼けてしまっています。塗り直す余裕はあまりありません。', NULL, NULL, NULL, NULL, 'サンケア', 'MK', NULL, NULL, NULL, 'fd1a8c095aa866408a69fde4978a30592f78ca545fa658956830056a8ebeed3d', '2026-09-26');
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (19, 'need', 'dummy', 'つけた香りがすぐ消えてしまう', '朝つけた香りが、お昼にはもうほとんど残っていません。夕方までほんのり続いてほしいです。', NULL, NULL, NULL, NULL, 'フレグランス', 'MK', NULL, NULL, NULL, 'e7c018f1597c8903ba8ea588cb0d815272e4ae7fc16116a08c46713b2a1f8981', '2026-09-26');
