INSERT INTO evaluations (id, seed_id, kind, summary, detail, dated) VALUES (1, 1, 'dropped', '整髪料への配合を検討したが、安定性の問題で見送り', '40℃保存4週で被膜形成能が低下。処方側での安定化が必要と判断し、当該期の企画では採用を見送った。', '2023-09');
INSERT INTO evaluations (id, seed_id, kind, summary, detail, dated) VALUES (2, 1, 'evaluated', '耐皮脂性の実機評価を実施済み', '人工皮脂塗布後8時間でのカール保持率は対照比+32%。官能評価でもベタつきの抑制を確認。', '2023-06');
INSERT INTO evaluations (id, seed_id, kind, summary, detail, dated) VALUES (3, 2, 'evaluated', '造形保持力と光沢の両立を確認', 'シリカ分散量0.5〜1.5%の範囲で光沢度を抑制しつつ弾性率を維持できることを確認。', '2022-12');
INSERT INTO evaluations (id, seed_id, kind, summary, detail, dated) VALUES (4, 2, 'unevaluated', '高湿度環境下での評価は未実施', '湿度80%以上の条件でのデータがない。夏季想定の企画では追加評価が必要。', '');
INSERT INTO evaluations (id, seed_id, kind, summary, detail, dated) VALUES (5, 3, 'evaluated', '損傷毛での水分蒸散抑制を確認', 'ブリーチ2回処理毛において、無処理比で水分蒸散量が18%低下。', '2024-04');
INSERT INTO evaluations (id, seed_id, kind, summary, detail, dated) VALUES (6, 7, 'dropped', 'ベースメイクへの展開を検討したが、使用感の課題で見送り', '密着性は目標を達成したが、塗布時の伸びが重く官能評価が基準を下回った。', '2024-08');
INSERT INTO evaluations (id, seed_id, kind, summary, detail, dated) VALUES (7, 8, 'unevaluated', '実使用条件での経時データが未取得', '光安定性は加速試験のみ。屋外実使用での検証は行っていない。', '');
INSERT INTO evaluations (id, seed_id, kind, summary, detail, dated) VALUES (8, 6, 'evaluated', 'パッチテストで低刺激性を確認', '24時間閉塞パッチにて既存処方比で刺激スコアが有意に低下。', '2022-07');
